import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import Module, {createRequire} from 'node:module';
import {JSDOM} from 'jsdom';

// Uses the real app bundle generated by vendor-catalog-brain-test.mjs.
// All persistence and fetches are synthetic; no network or live data is used.
const dir = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);
const dom = new JSDOM('<div id="root"></div>', {url:'http://localhost/'});
Object.assign(globalThis, {window:dom.window, document:dom.window.document, HTMLElement:dom.window.HTMLElement, localStorage:dom.window.localStorage, sessionStorage:dom.window.sessionStorage, IS_REACT_ACT_ENVIRONMENT:true, requestAnimationFrame:f=>setTimeout(()=>f(performance.now()+1000),0), cancelAnimationFrame:clearTimeout});
Object.defineProperty(globalThis,'navigator',{value:window.navigator,configurable:true});
window.matchMedia=()=>({matches:false,addListener(){},removeListener(){},addEventListener(){},removeEventListener(){}});
globalThis.matchMedia=window.matchMedia;
globalThis.__db=new Proxy({fetchPeriodLocks:async()=>[]},{get:(o,k)=>o[k]||(()=>{throw new Error('Unexpected database access: '+String(k));})});
const React=require('react'); const {act}=React; const {createRoot}=require('react-dom/client');
const bundlePath=path.join(dir,'vendor-catalog-bundle-ui.cjs');
let app;
if(process.argv.includes('--mutant')){
  let source=fs.readFileSync(bundlePath,'utf8');
  const idx=Number(process.argv.at(-1))||0;
  const wire=idx===1?'if (uploadBusyRef.current ||':'VendorCatalogPanel, { vendor: vend, customSops, setPage, addSop, notify, changeVendorCatalog }';
  assert.ok(source.includes(wire),'callback-wire mutation anchor exists');
  source=source.replace(wire,idx===1?'if (false ||':'VendorCatalogPanel, { vendor: vend, customSops, setPage, addSop, notify, changeVendorCatalog: undefined }');
  const isolated=new Module(bundlePath); isolated.filename=bundlePath; isolated.paths=Module._nodeModulePaths(dir);
  isolated._compile(source,bundlePath); app=isolated.exports;
}else app=require(bundlePath);
const {Vendor360Page,DirectoryPage}=app;
const vendors=[{id:'V-test',name:'Acme Synthetic Furniture',contact:'Pat',email:'pat@example.test',phone:'555-0100',category:'Furniture'},{id:'V-other',name:'Other Synthetic Supply',contact:'Sam',email:'sam@example.test',phone:'555-0101',category:'Furniture'}];
const record=(vendor,title)=>({id:'VCAT-'+vendor.id,title,cat:'VendorCatalog',icon:'book',custom:true,content:JSON.stringify({vendorId:vendor.id,vendorName:vendor.name,title,edition:'2026',url:'https://files.test/'+vendor.id+'.json',pdfUrl:'https://files.test/'+vendor.id+'.pdf',pageCount:1,productCount:0,sectionCount:0,groups:[],hasPrices:false})});
const original=record(vendors[0],'Exact Synthetic Wrong Catalogue');
const other=record(vendors[1],'Other Catalogue Must Remain');
let persisted=structuredClone([original,other]);
const untouchedOther=JSON.stringify(other);
const fetches=[];
globalThis.fetch=async url=>{
  fetches.push(String(url));
  const row=[original,other].find(x=>JSON.parse(x.content).url===String(url));
  assert.ok(row,'no unexpected network URL: '+url);
  return {ok:true,status:200,json:async()=>({v:1,...JSON.parse(row.content),pages:[],products:[],sections:[],headers:[]})};
};
window.open=()=>{throw new Error('Unexpected external navigation');};
const calls=[]; const notices=[]; const pages=[]; let pending;
let root;
const callback=async(sop,action,updates)=>{
  calls.push({sop:structuredClone(sop),action,updates});
  await new Promise((resolve,reject)=>{pending={resolve,reject};});
  const {catalogChange}=await import('../../src/catalogLifecycle.js');
  const row={...sop,...catalogChange(sop,action,updates)};
  persisted=persisted.map(x=>x.id===row.id?row:x);
  renderVendor();
  return row;
};
const props=()=>({jobs:[],lineItems:[],vendors,customers:[],reps:[],getJobFinancials:()=>({}),getJobItems:()=>[],setPage:p=>pages.push(p),setSelectedJob(){},notify:m=>notices.push(m),updateVendor(){},jobNum:()=>'',customSops:structuredClone(persisted),addSop(){throw new Error('Unexpected upload');},deleteSop(){throw new Error('Generic delete must not be used');},changeVendorCatalog:callback,setFocusSopId(){}});
function renderVendor(){root.render(React.createElement(Vendor360Page,props()));}
const settle=async()=>{await act(async()=>{await new Promise(r=>setTimeout(r,0));});};
const buttons=(scope=document)=>[...scope.querySelectorAll('button')];
const button=(name,scope=document)=>buttons(scope).find(x=>x.textContent.trim()===name);
const dialog=()=>document.querySelector('[role="dialog"][aria-label="Delete Catalog"]');
const text=()=>document.body.textContent;
async function click(el){assert.ok(el,'expected control exists');await act(async()=>{el.click();});}
async function mount(){window._viewVendorId='V-test';root=createRoot(document.getElementById('root'));await act(async()=>renderVendor());await settle();}
async function unmount(){await act(async()=>root.unmount());document.body.innerHTML='<div id="root"></div>';}
function otherUnchanged(){assert.equal(JSON.stringify(persisted.find(x=>x.id===other.id)),untouchedOther,'another vendor stays byte-for-byte unchanged');}

await mount();
await click(button('Edit Catalog'));
let edit=document.querySelector('[aria-label="Edit Catalog"]');
assert.ok(edit);assert.match(edit.textContent,/Only title and edition change/);
await click(button('Cancel',edit));assert.equal(calls.length,0,'cancel edit does not save');
// Moving to a different vendor dismisses old confirmation and cannot relabel its target.
await click(button('Delete Catalog'));
window._viewVendorId='V-other';await act(async()=>renderVendor());await settle();
assert.equal(dialog(),null,'vendor navigation dismisses old target');assert.equal(calls.length,0);
window._viewVendorId='V-test';await act(async()=>renderVendor());await settle();
assert.ok(button('Delete Catalog'),'Delete Catalog visible on actual vendor page');
await click(button('Delete Catalog'));
assert.ok(dialog(),'explicit confirmation opens');
assert.ok(dialog().textContent.includes(original.title),'dialog names exact catalogue');
assert.ok(dialog().textContent.includes(vendors[0].name),'dialog names exact vendor');
assert.match(dialog().textContent,/files are kept|restore/i,'dialog explains recovery');
await click(button('Cancel',dialog()));
assert.equal(dialog(),null);assert.equal(calls.length,0,'Cancel performs no write');
await click(button('Delete Catalog'));
const confirm=button('Delete Catalog',dialog());
await act(async()=>{confirm.click();confirm.click();confirm.click();});
assert.equal(calls.length,1,'repeated confirmation starts exactly one mutation');
assert.deepEqual(calls[0].sop,original,'exact selected row passed to callback');assert.equal(calls[0].action,'delete');
assert.ok(button('Saving...',dialog()).disabled,'confirmation disabled while pending');
assert.ok(button('Cancel',dialog()).disabled,'cancel disabled while pending');
assert.equal(persisted[0].cat,'VendorCatalog','not removed before confirmed save');
await act(async()=>pending.reject(new Error('Synthetic permission failure')));
assert.ok(dialog(),'failure keeps confirmation available');
assert.match(text(),/Synthetic permission failure/,'failure shown to user');
assert.equal(persisted[0].cat,'VendorCatalog');otherUnchanged();
await click(button('Delete Catalog',dialog()));
assert.equal(calls.length,2,'retry starts one new attempt');
await act(async()=>pending.resolve());await settle();
assert.equal(dialog(),null,'successful deletion closes confirmation');
assert.equal(persisted[0].cat,'VendorCatalogDeleted');
assert.equal(persisted[0].content,original.content,'archived metadata preserved');
assert.match(text(),/No catalogue loaded for this vendor yet/);
assert.ok(button('Restore catalogue'),'recoverable archive visible');
assert.equal(button('Delete Catalog'),undefined,'no active catalogue left to delete');
otherUnchanged();
await unmount();await mount();
assert.ok(button('Restore catalogue'),'archive survives remount from persisted rows');
await click(button('Restore catalogue'));
assert.equal(calls.length,2,'restore asks before changing state');
await click(button('Restore Catalog',document.querySelector('[aria-label="Restore Catalog"]')));
assert.equal(calls.length,3);assert.equal(calls[2].action,'restore');
assert.equal(persisted[0].cat,'VendorCatalogDeleted','restore waits for persistence');
await act(async()=>pending.resolve());await settle();
assert.equal(persisted[0].cat,'VendorCatalog');
assert.ok(button('Delete Catalog'),'restored catalogue is active again');
assert.equal(button('Restore catalogue'),undefined);otherUnchanged();
await unmount();await mount();
assert.ok(button('Delete Catalog'),'restored state survives remount');
await unmount();

// Persisted title/edition edits retain all original file and product metadata.
await mount();await click(button('Edit Catalog'));
const nativeSet=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
async function type(input,value){await act(async()=>{input.focus();nativeSet.call(input,value);input.dispatchEvent(new window.Event('input',{bubbles:true}));});}
await type(document.querySelector('input[aria-label="Catalogue title"]'),'Corrected title');
await type(document.querySelector('input[aria-label="Edition"]'),'');
await click(button('Save Catalog'));assert.equal(persisted[0].title,original.title,'edit waits for persistence');
await act(async()=>pending.resolve());await settle();
assert.equal(persisted[0].title,'Corrected title');
assert.deepEqual(JSON.parse(persisted[0].content),{...JSON.parse(original.content),title:'Corrected title',edition:''});otherUnchanged();
assert.match(text(),/Corrected title/);await unmount();await mount();assert.match(text(),/Corrected title/);await unmount();
// Multiple editions remain separately selectable, including identical title/edition uploads.
const second={...original,id:'VCAT-second',title:'Second catalogue',content:JSON.stringify({...JSON.parse(original.content),title:'Second catalogue'})};
persisted=[original,second,other];await mount();
const choose=document.querySelector('select[aria-label="Select catalogue"]');assert.ok(choose);
await act(async()=>{Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype,'value').set.call(choose,second.id);choose.dispatchEvent(new window.Event('change',{bubbles:true}));});await settle();
await click(button('Delete Catalog'));assert.ok(dialog().textContent.includes(second.id));assert.ok(dialog().textContent.includes(second.title));await click(button('Cancel',dialog()));await unmount();
// Upload waits for the actual row insert and shows failed persistence instead of a false success.
persisted=[];root=createRoot(document.getElementById('root'));window._viewVendorId='V-test';let insertPending,insertCalls=0;
globalThis.__ciIngest=async()=>({id:'VCAT-new',rec:{...JSON.parse(original.content),title:'New upload'},stats:{pages:1,rows:0,codes:0,sections:0,priceFigures:0,images:0,pdfPieces:1},warnings:[]});
const uploadProps={...props(),addSop:async sop=>{insertCalls++;return new Promise((resolve,reject)=>insertPending={resolve,reject,sop});}};
await act(async()=>root.render(React.createElement(Vendor360Page,uploadProps)));await settle();await click(button('Upload catalogue'));
const pdf=document.querySelector('input[type=file]');Object.defineProperty(pdf,'files',{value:[{name:'new.pdf',size:123,type:'application/pdf'}],configurable:true});await act(async()=>pdf.dispatchEvent(new window.Event('change',{bubbles:true})));
const uploadButton=button('Upload');await act(async()=>{uploadButton.click();uploadButton.click();uploadButton.click();});await settle();assert.equal(insertCalls,1,'repeated upload click inserts only one new catalogue');assert.doesNotMatch(text(),/Loaded: New upload/);assert.ok(button('Working...'));
await act(async()=>insertPending.reject(Error('Synthetic insert denied')));await settle();assert.match(text(),/Synthetic insert denied/);assert.doesNotMatch(text(),/Loaded: New upload/);assert.ok(button('Upload'));
await click(button('Upload'));await settle();await act(async()=>insertPending.resolve(insertPending.sop));await settle();assert.match(text(),/Loaded: New upload/);await unmount();
persisted=[original,other];

// Directory must keep archived-only vendors reachable instead of opening upload.
persisted=persisted.map(x=>x.id===original.id?{...x,cat:'VendorCatalogDeleted'}:x);
root=createRoot(document.getElementById('root'));
await act(async()=>root.render(React.createElement(DirectoryPage,{...props(),confirm:async()=>true,addVendor(){},deleteVendor(){},forceDeleteVendor(){},forceDeleteCustomer(){},forceDeleteRep(){},updateCustomer(){},addCustomer(){},deleteCustomer(){},updateRep(){},addRep(){},deleteRep(){}})));
await settle();
const vendorTab=buttons().find(x=>/^Vendors/.test(x.textContent.trim()));
if(vendorTab)await click(vendorTab);
const targetRow=[...document.querySelectorAll('tr')].find(x=>x.textContent.includes(vendors[0].name));
assert.ok(targetRow,'Directory shows target vendor');
await click(button('Catalogue',targetRow));
assert.equal(pages.at(-1),'vendor360','archived-only Directory catalogue opens vendor page');
assert.equal(window._viewVendorId,'V-test');
assert.doesNotMatch(text(),/Upload catalogue >>/,'archive navigation is not upload');
otherUnchanged();await unmount();
assert.ok(fetches.every(x=>x.startsWith('https://files.test/')),'all requests were synthetic');
console.log('PASS catalogue controls UI: exact confirmation, Cancel, repeat-click lock, persistence failure/retry, restore/reload, vendor isolation, archived Directory navigation');
